Prompt-4.templateFn:
const { text, sourceLang = 'auto', targetLang, style = 'natural' } = params;

// prettier-ignore
return `
  Please translate the following text to ${targetLang}:

  ${text}

  Translation requirements:
  - ${sourceLang === 'auto' ? 'Detect the source language automatically' : 'Source language: ' + sourceLang}
  - Target language: ${targetLang}
  - Translation style: ${style} (preserve the original tone and meaning)
  - Maintain formatting and structure
  - Ensure cultural appropriateness

  Provide only the translated text without explanations.
`;

Prompt-5.templateFn:
const { text, detailed = false } = params;

// prettier-ignore
return `
  Please analyze the sentiment of the following text:

  "${text}"

  Provide a sentiment analysis that includes:
  - Overall sentiment (positive, negative, neutral, mixed)
  - Confidence score (0-100%)
  - Key emotional indicators
  ${detailed ? '- Detailed emotion breakdown (joy, anger, fear, sadness, surprise, etc.)\n- Specific phrases that indicate each emotion\n- Intensity levels for each emotion detected' : ''}

  Format your response as a clear, structured analysis.
`;

Prompt-user-message-analysis.templateFn:
const { userMessage, additionalContext = '' } = params;

// prettier-ignore
return `
  Analyze the following user message and extract key information:

  User Message: "${userMessage}"

  ${additionalContext ? `Additional Context: ${additionalContext}

` : ''}

  Please provide a detailed analysis including:
  1. Summary: A brief summary of what the user is asking or saying
  2. Intent: The primary intent or goal of the message (e.g., question, request, feedback, etc.)
  3. Entities: Key entities, topics, or concepts mentioned
  4. Category: Categorize the message (e.g., technical_support, general_inquiry, feature_request, etc.)
  5. Urgency: Assess the urgency level (low, medium, high)

  Format your response as a structured analysis.
`;

Action-stream-to-fe.actionFn:
const { message } = params;

const result = await services.llm.streamText({
  model: { provider: 'openai', model: 'gpt-4o' },
  prompt: message,
  system: 'You are a helpful assistant.',
  temperature: 0.7,
  maxTokens: 100,
});

for await (const textPart of result.textStream) {
  services.logger.info('Streaming text to FE', { textPart });

  services.emitter.sendToPlugin('agent', {
    type: 'TOKEN_STREAM',
    token: textPart
  });
}

await result.finishReason

services.emitter.sendToPlugin('agent', {
  type: 'LLM_DONE',
});

