Prompt: Generate a transaction that builds a three-level thread hierarchy and demonstrates safeLink cycle prevention
Query:	const root = tx(EARS.Entity.Thread)
.put(‘title’, ‘Root Thread’)
.id();
const child = tx(EARS.Entity.Thread)
.put(‘title’, ‘Child Thread’)
.id();
const grandchild = tx(EARS.Entity.Thread)
.put(‘title’, ‘Grandchild Thread’)
.id();
tx(root).safeLink(EARS.RelKind.parent_of, child);
tx(child).safeLink(EARS.RelKind.parent_of, grandchild);
try {
tx(grandchild).safeLink(EARS.RelKind.parent_of, root, { preventCycles: true });
} catch (error) {
return { hierarchy: { root, child, grandchild }, cyclePreventionWorking: true };
}

Prompt: Generate a transaction that creates Agent, Thread, and Tag entities and links them with contains, has, and symmetric relates_to relations
Query:	const agentId  = tx(EARS.Entity.Agent) .put(‘name’, ‘Multi-Agent’).id();
const threadId = tx(EARS.Entity.Thread).put(‘title’, ‘Multi-Agent Thread’).id();
const tagId    = tx(EARS.Entity.Tag)  .put(‘name’, ‘important’).put(‘color’, ‘#FF0000’).id();
tx(agentId) .link(EARS.RelKind.contains , threadId);
tx(threadId).link(EARS.RelKind.has      , tagId);
tx(agentId) .link(EARS.RelKind.relates_to, threadId, { symmetric: true });
return {
entities    : { agentId, threadId, tagId },
agentThreads: qx(agentId) .linksTo(‘contains’, EARS.Entity.Thread).ids(),
threadTags  : qx(threadId).linksTo(‘has’,      EARS.Entity.Tag)   .ids()
};

Prompt: Generate a transaction that batch-updates multiple attributes on an Agent entity
Query:	const entityId = tx(EARS.Entity.Agent).put(‘name’, ‘Agent Smith’).id();
tx(entityId).batchPut({
status      : ‘active’,
lastActive  : Date.now(),
capabilities: [‘chat’, ‘analysis’, ‘search’],
config      : { temperature: 0.7, maxTokens: 1000 }
});
return qx(entityId).pickAll();

Prompt: Generate a transaction that grants and revokes roles on an Agent and enforces a primary role
Query:	const agentId = tx(EARS.Entity.Agent)
.put(‘name’, ‘Role Test Agent’)
.grant(‘assistant’)
.grant(‘analyzer’)
.id();
const initialRoles = getRoles(agentId);
tx(agentId).revoke(‘assistant’).grant(‘supervisor’).ensure(‘primary’);
const finalRoles = getRoles(agentId);
return { agentId, initialRoles, finalRoles };

Prompt: Generate a transaction that creates a Thread and an initial Message linked to it, then returns both ids
Query:	const threadId = tx(EARS.Entity.Thread)
.put(‘title’, ‘Customer Support’)
.put(‘status’, ‘open’)
.put(‘createdAt’, Date.now())
.id();
const messageId = tx(EARS.Entity.Message)
.put(‘text’, ‘Hello, how can I help you today?’)
.put(‘timestamp’, Date.now())
.put(‘sender’, ‘assistant’)
.link(EARS.RelKind.belongs_to, threadId)
.id();
tx(threadId).link(EARS.RelKind.contains, messageId);
return { threadId, messageId };

Prompt: Generate a transaction that deletes a Tag entity and confirms removal
Query:	const tempId = tx(EARS.Entity.Tag)
.put(‘name’, ‘temporary’)
.put(‘color’, ‘#808080’)
.id();
const exists = qx(tempId).pickOne([‘id’, ‘name’]);
tx(tempId).destroy();
const afterDelete = qx(tempId).pickOne([‘id’]);
return { created: exists, afterDelete: afterDelete || ‘Entity not found (successfully deleted)’ };
